-- Update MOTD with Fung Wan Online Preservation Project welcome message.
-- Message split across 6 chunks (engine concatenates MsgText1..MsgText[Count]).

USE fwworlddevdb;

UPDATE MOTD SET
  MsgText1 = UNHEX(''),
  MsgText2 = UNHEX(''),
  MsgText3 = UNHEX(''),
  MsgText4 = UNHEX(''),
  MsgText5 = UNHEX(''),
  MsgText6 = UNHEX(''),
  MsgText7 = NULL,
  MsgText8 = NULL,
  MsgText9 = NULL,
  MsgText10 = NULL,
  Count = 6
WHERE ID IN (0, 1, 2, 3);
